F=[('U','V'),('U','W'),('WX','Y'),('WX','Z'),('V','X')]
def closure(attrs):
    c=set(attrs); changed=True
    while changed:
        changed=False
        for l,r in F:
            if set(l)<=c and not set(r)<=c: c|=set(r); changed=True
    return c
opts={'A':('VW','YZ'),'B':('WX','YZ'),'C':('VW','U'),'D':('VW','Y')}
for k,(l,r) in opts.items():
    c=closure(l); print(k, l+'->'+r, 'closure', ''.join(sorted(c)), 'derivable:', set(r)<=c)
